const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
