/** match from a mapping like 'A-q, B-r, C-p, D-s': builds three wrong codes by swapping pairs */
const xmt = (level, sub, title, list1, list2, map, sol, trap) => {
  const m = map.split(',').map((t) => t.trim().split('-')); const code = (a) => a.map(([k, v]) => `${k}-${v}`).join(', ');
  const sw = (i, j) => { const b = m.map(([k, v]) => [k, v]); const t = b[i][1]; b[i][1] = b[j][1]; b[j][1] = t; return code(b); };
  const wr = [sw(0, 1), sw(2, 3), sw(0, 2), sw(1, 3), sw(0, 3)].filter((c) => c !== code(m));
  xmat(level, sub, title, list1.map((t, i) => `${'ABCD'[i]}. ${t}`), list2.map((t, i) => `${'pqrst'[i]}. ${t}`), code(m), wr.slice(0, 3), sol, trap);
};
